SELECT COUNT(*) AS cnt
FROM (
  SELECT person1_id AS id FROM Knows
  UNION
  SELECT person2_id AS id FROM Knows
) t;

SELECT COUNT(*) AS cnt
FROM (
  SELECT person1_id AS id FROM Knows
  UNION
  SELECT person2_id AS id FROM Knows
) t;

SELECT COUNT(*) AS cnt
FROM (
  SELECT person1_id AS pid FROM Knows
  UNION
  SELECT person2_id AS pid FROM Knows
) t;

SELECT COUNT(*) AS count
FROM (
    SELECT person1_id AS person_id FROM Knows
    UNION
    SELECT person2_id AS person_id FROM Knows
) AS friends;

SELECT COUNT(*) AS person_count
FROM (
    SELECT person1_id AS person_id FROM Knows
    UNION
    SELECT person2_id AS person_id FROM Knows
) AS friends;

SELECT COUNT(*) AS friend_count
FROM (
    SELECT person1_id AS person_id FROM Knows
    UNION
    SELECT person2_id AS person_id FROM Knows
) AS friends;

SELECT COUNT(DISTINCT friend_id) AS friend_count
FROM (
    SELECT person2_id AS friend_id FROM Knows WHERE person1_id = 933
    UNION
    SELECT person1_id AS friend_id FROM Knows WHERE person2_id = 933
) AS friends;

SELECT COUNT(*) AS friend_count
FROM (
    SELECT person2_id AS friend_id FROM Knows WHERE person1_id = 933
    UNION
    SELECT person1_id AS friend_id FROM Knows WHERE person2_id = 933
) AS friends;
